def HasVanishingDyadicTrace (S : X →L[𝕜] Y) : Prop :=
  ∀ (A : Y →L[𝕜] IntervalL1 𝕜) (B : IntervalL1 𝕜 →L[𝕜] X),
    Tendsto (fun n => DyadicTrace.trace n (A.comp (S.comp B))) atTop (𝓝 0)

